// Only parse authenticated native owner status lines; no other input
// can change persisted outer "mtu" or claim OS Applied. This is a
// display receipt, not a separate tunnel owner.
static string Plan029Field(string line,string name) {
    string prefix = name + "=";
    foreach (string part in line.Split(new[] {' '}, StringSplitOptions.RemoveEmptyEntries))
        if (part.StartsWith(prefix, StringComparison.Ordinal)) return part.Substring(prefix.Length);
    return "";
}
void Plan029ReadOnlyStatus(string line) {
    if (connectedId == null || !session.Active) return;
    uint effective, inner, applied;
    if (line.StartsWith("WBD_WINDOWS_COLD_MSS_BUDGET_V1 ", StringComparison.Ordinal)) {
        if (uint.TryParse(Plan029Field(line,"effective_outer_mtu"), out effective) &&
            uint.TryParse(Plan029Field(line,"inner_mtu_planned"), out inner) &&
            effective>=576 && effective<=1500 && inner>0 && inner<=effective)
            mtuStatus.Text = "有效外层上限：" + effective + "B · 自动内层 MTU：" +
                inner + "B（计划） · OS 应用：未验证";
    }
    if (line.StartsWith("WBD_WINDOWS_INNER_OS_MTU_APPLIED_V1 ", StringComparison.Ordinal)) {
        if (uint.TryParse(Plan029Field(line,"applied"), out applied) &&
            uint.TryParse(Plan029Field(line,"outer_config"), out effective) &&
            uint.TryParse(Plan029Field(line,"planned"), out inner) &&
            applied==inner && inner>0 && inner<=effective && effective<=1500)
            mtuStatus.Text = "外层配置：" + effective + "B · 自动内层 MTU：" +
                applied + "B · OS 应用：已读回（仍须独立 OS Applied 总回执）";
    }
    if (line.StartsWith("WBD_PLAN029_BOOTSTRAP_DNS_SELECTED ", StringComparison.Ordinal)) {
        IPAddress selected;
        string value=Plan029Field(line,"selected4");
        if (IPAddress.TryParse(value,out selected) &&
            selected.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork)
            ShowState("域名已解析 → " + value + " · 正在认证，系统尚未 Applied");
    }
}
